        src = """
            int f(int x) {
                _Generic(x, int: 0);
                if (x) _Generic(x, default: 1);
                else _Generic(x, default: 2);
                for (_Generic(x, default: 3); _Generic(x, default: 4);
                     _Generic(x, default: 5))
                    _Generic(x, default: 6);
