            "int v = _Generic(x, default: s).field;",
            "int v = _Generic(x, default: p)->field;",
            "int v = _Generic(x, default: y)++;",
            "int v = -_Generic(x, int: 1);",
            "int v = sizeof(_Generic(x, int: 1));",
        ]
        for reduce_parentheses in (False, True):
            for src in snippets:
